def parse(line):
    """Return ("<method> <path>", latency_ms) for a good line, or None for a malformed one."""
    parts = line.split()
    if len(parts) != 5:
        return None
    _, method, path, status, latency = parts
    digits = latency[:-2]
    if not (status.isascii() and status.isdigit() and latency.endswith("ms") and digits.isascii() and digits.isdigit()):
        return None
    return f"{method} {path}", int(digits)


def nearest_rank(sorted_values, percent):
    rank = -(-percent * len(sorted_values) // 100)    # ceil(percent * n / 100) in integer arithmetic
    return sorted_values[rank - 1]                    # ranks start at 1, list indexes at 0


def latency_percentiles(lines):
    latencies = {}                                    # endpoint -> list of latencies
    malformed = 0
    for line in lines:
        parsed = parse(line)
        if parsed is None:
            malformed += 1
            continue
        endpoint, latency = parsed
        latencies.setdefault(endpoint, []).append(latency)

    stats = {}
    for endpoint, values in latencies.items():
        values.sort()
        stats[endpoint] = {
            "count": len(values),
            "p50": nearest_rank(values, 50),
            "p95": nearest_rank(values, 95),
            "p99": nearest_rank(values, 99),
        }
    return stats, malformed
